export const SCRIPTS: { code: string; exports: string[] }[] = [{"code":"\n  // ── Tab switching ──\n  function switchTab(name, btn) {\n    document.querySelectorAll('.form-panel').forEach(p => p.classList.remove('active'));\n    document.querySelectorAll('.form-tab').forEach(b => b.classList.remove('active'));\n    document.getElementById('tab-' + name).classList.add('active');\n    btn.classList.add('active');\n  }\n\n  // ── Generic form handler ──\n  ['general','project','careers','press'].forEach(id => {\n    const form = document.getElementById(id + '-form');\n    if (!form) return;\n    form.addEventListener('submit', async e => {\n      e.preventDefault();\n      const btn     = document.getElementById(id + '-btn');\n      const success = document.getElementById(id + '-success');\n      const error   = document.getElementById(id + '-error');\n\n      btn.textContent = 'Sending…';\n      btn.disabled    = true;\n      if (error) error.style.display = 'none';\n\n      try {\n        const res = await fetch(form.action, {\n          method: 'POST',\n          body: new FormData(form),\n          headers: { 'Accept': 'application/json' }\n        });\n        if (res.ok) {\n          form.reset();\n          btn.style.display     = 'none';\n          success.style.display = 'block';\n        } else { throw new Error(); }\n      } catch {\n        if (error) error.style.display = 'block';\n        btn.textContent = btn.textContent.replace('Sending…', 'Try again →');\n        btn.disabled    = false;\n      }\n    });\n  });\n","exports":["switchTab"]}];
